package task.member.presentation.error

import org.springframework.http.HttpStatusCode

/** 오류 응답(ProblemDetail)의 `code` 값. 목록과 의미는 docs/common/api-conventions.md (POL-API-002). */
enum class ErrorCode(
  val code: String,
  val status: Int,
  val codeName: String,
  val description: String,
) {
  BAD_REQUEST("BAD_REQUEST", 400, "잘못된 요청", "요청 형식이 올바르지 않습니다."),
  VALIDATION_FAILED("VALIDATION_FAILED", 400, "입력값 검증 실패", "요청 값이 허용된 조건을 충족하지 않습니다."),
  UNAUTHORIZED("UNAUTHORIZED", 401, "인증 필요", "인증이 필요합니다."),
  FORBIDDEN("FORBIDDEN", 403, "접근 거부", "접근 권한이 없습니다."),
  NOT_FOUND("NOT_FOUND", 404, "대상 없음", "요청한 경로나 자원을 찾을 수 없습니다."),
  METHOD_NOT_ALLOWED("METHOD_NOT_ALLOWED", 405, "허용되지 않은 요청 방법", "지원하지 않는 HTTP 메서드입니다."),
  NOT_ACCEPTABLE("NOT_ACCEPTABLE", 406, "응답 형식 불일치", "요청한 형식으로 응답할 수 없습니다."),
  CONFLICT("CONFLICT", 409, "상태 충돌", "현재 자원의 상태와 요청이 충돌합니다."),
  UNSUPPORTED_MEDIA_TYPE("UNSUPPORTED_MEDIA_TYPE", 415, "지원하지 않는 본문 형식", "요청 본문의 형식을 지원하지 않습니다."),
  INTERNAL_ERROR("INTERNAL_ERROR", 500, "내부 처리 오류", "요청을 처리하지 못했습니다."),
  GROUP_RESPONSE_INVALID_JSON(
    "GROUP_RESPONSE_INVALID_JSON",
    502,
    "그룹 JSON 오류",
    "그룹 응답의 JSON 형식이 올바르지 않습니다.",
  ),
  GROUP_RESPONSE_CONTRACT_VIOLATION(
    "GROUP_RESPONSE_CONTRACT_VIOLATION",
    502,
    "그룹 응답 규격 오류",
    "그룹 응답이 정의된 규격을 충족하지 않습니다.",
  ),
  GROUP_RESPONSE_UNSUPPORTED_MEDIA_TYPE(
    "GROUP_RESPONSE_UNSUPPORTED_MEDIA_TYPE",
    502,
    "그룹 응답 형식 오류",
    "그룹 응답의 매체 유형이 올바르지 않습니다.",
  ),
  GROUP_RESPONSE_TOO_LARGE("GROUP_RESPONSE_TOO_LARGE", 502, "그룹 응답 크기 초과", "그룹 응답이 허용 크기를 초과했습니다."),
  GROUP_UPSTREAM_FAILURE("GROUP_UPSTREAM_FAILURE", 502, "그룹 서버 오류", "그룹 서버에서 정상 응답을 받지 못했습니다."),
  GROUP_SERVICE_TIMEOUT("GROUP_SERVICE_TIMEOUT", 504, "그룹 응답 시간 초과", "그룹 응답 대기 시간이 초과되었습니다."),
  GROUP_SERVICE_UNAVAILABLE(
    "GROUP_SERVICE_UNAVAILABLE",
    503,
    "그룹 서비스 이용 불가",
    "그룹 정보를 일시적으로 조회할 수 없습니다.",
  ),
  SERVICE_UNAVAILABLE("SERVICE_UNAVAILABLE", 503, "서비스 이용 불가", "일시적으로 요청을 처리할 수 없습니다.");

  companion object {
    /** 상태 코드에 맞는 일반 코드. 목록에 없는 상태는 4xx면 BAD_REQUEST, 5xx면 INTERNAL_ERROR. */
    fun of(status: HttpStatusCode): ErrorCode =
      when (status.value()) {
        502 -> GROUP_UPSTREAM_FAILURE
        504 -> GROUP_SERVICE_TIMEOUT
        else ->
          entries.firstOrNull {
            it.status == status.value() &&
              it !in setOf(VALIDATION_FAILED, GROUP_SERVICE_UNAVAILABLE)
          } ?: if (status.is5xxServerError) INTERNAL_ERROR else BAD_REQUEST
      }
  }
}
package task.member.presentation.error

import com.fasterxml.jackson.annotation.JsonInclude
import java.net.URI
import org.springframework.http.ProblemDetail

/** about:blank도 필수 type으로 직렬화한다. Spring의 확장 속성 처리는 유지한다(POL-API-002). */
class MemberProblemDetail(source: ProblemDetail) : ProblemDetail(source) {
  @JsonInclude(JsonInclude.Include.ALWAYS)
  override fun getType(): URI = super.getType() ?: URI.create("about:blank")
}
package task.member.presentation.error

import org.slf4j.LoggerFactory
import org.springframework.http.HttpHeaders
import org.springframework.http.HttpStatus
import org.springframework.http.HttpStatusCode
import org.springframework.http.ProblemDetail
import org.springframework.http.ResponseEntity
import org.springframework.web.bind.MethodArgumentNotValidException
import org.springframework.web.bind.annotation.ExceptionHandler
import org.springframework.web.bind.annotation.RestControllerAdvice
import org.springframework.web.context.request.WebRequest
import org.springframework.web.method.annotation.HandlerMethodValidationException
import org.springframework.web.servlet.mvc.method.annotation.ResponseEntityExceptionHandler
import task.member.application.exception.GroupProxyException
import task.member.application.exception.GroupResponseContractException
import task.member.application.exception.GroupResponseJsonException
import task.member.application.exception.GroupResponseMediaException
import task.member.application.exception.GroupResponseSizeException
import task.member.application.exception.GroupServiceConfigurationException
import task.member.application.exception.GroupServiceTimeoutException
import task.member.application.exception.GroupServiceUnavailableException
import task.member.application.exception.GroupUpstreamFailureException
import task.member.application.exception.InvalidMemberQueryException
import task.member.application.exception.MemberNotFoundException

/**
 * 모든 오류 응답을 RFC 9457 ProblemDetail + `code`로 만든다(POL-API-002).
 *
 * Spring MVC 표준 예외는 상위 클래스가 ProblemDetail을 만들고, 여기서 `code`를 붙인다. 처리되지 않은 예외는 내부 정보를 응답에 넣지 않고
 * INTERNAL_ERROR로 바꾼다.
 */
@RestControllerAdvice
class ProblemDetailsExceptionHandler : ResponseEntityExceptionHandler() {
  private val log = LoggerFactory.getLogger(javaClass)

  @ExceptionHandler(InvalidMemberQueryException::class)
  fun handleInvalidMemberQuery(): ProblemDetail = memberProblem(ErrorCode.VALIDATION_FAILED)

  @ExceptionHandler(MemberNotFoundException::class)
  fun handleMemberNotFound(): ProblemDetail = memberProblem(ErrorCode.NOT_FOUND)

  private fun memberProblem(code: ErrorCode): ProblemDetail {
    SafeErrorLog.record(code)
    return ProblemDetail.forStatusAndDetail(HttpStatusCode.valueOf(code.status), code.description)
      .apply {
        title = code.codeName
        setProperty(CODE, code.code)
      }
      .let(::MemberProblemDetail)
  }

  override fun handleExceptionInternal(
    ex: Exception,
    body: Any?,
    headers: HttpHeaders,
    statusCode: HttpStatusCode,
    request: WebRequest,
  ): ResponseEntity<Any>? {
    val response = super.handleExceptionInternal(ex, body, headers, statusCode, request)
    val problem = response?.body as? ProblemDetail
    if (problem != null && problem.properties?.containsKey(CODE) != true) {
      val code =
        when (ex) {
          is MethodArgumentNotValidException,
          is HandlerMethodValidationException -> ErrorCode.VALIDATION_FAILED
          else -> ErrorCode.of(statusCode)
        }
      SafeErrorLog.record(code, ex)
      problem.setProperty(CODE, code.code)
      problem.title = code.codeName
      if (problem.detail == null) problem.detail = code.description
    }
    return response?.let {
      ResponseEntity(
        if (problem != null) MemberProblemDetail(problem) else it.body,
        it.headers,
        it.statusCode,
      )
    }
  }

  @ExceptionHandler(GroupServiceUnavailableException::class)
  fun handleGroupUnavailable(): ProblemDetail = groupProblem(ErrorCode.GROUP_SERVICE_UNAVAILABLE)

  @ExceptionHandler(GroupProxyException::class)
  fun handleGroupProxy(ex: GroupProxyException): ProblemDetail =
    groupProblem(
      when (ex) {
        is GroupResponseJsonException -> ErrorCode.GROUP_RESPONSE_INVALID_JSON
        is GroupResponseContractException -> ErrorCode.GROUP_RESPONSE_CONTRACT_VIOLATION
        is GroupResponseMediaException -> ErrorCode.GROUP_RESPONSE_UNSUPPORTED_MEDIA_TYPE
        is GroupResponseSizeException -> ErrorCode.GROUP_RESPONSE_TOO_LARGE
        is GroupUpstreamFailureException -> ErrorCode.GROUP_UPSTREAM_FAILURE
