  GROUP_MEMBERSHIP_NOT_FOUND("GROUP_MEMBERSHIP_NOT_FOUND", 404, "그룹 소속 없음", "그룹 소속을 찾을 수 없습니다."),
  GROUP_MEMBERSHIP_AMBIGUOUS(
    "GROUP_MEMBERSHIP_AMBIGUOUS",
    500,
    "소속 정합성 오류",
    "단일 그룹 소속 조건에 맞지 않습니다.",
  ),
  INTERNAL_ERROR("INTERNAL_ERROR", 500, "내부 처리 오류", "요청을 처리하지 못했습니다."),
  INTERNAL_ACCESS_DENIED("INTERNAL_ACCESS_DENIED", 403, "내부 호출 거부", "내부 서비스 호출 키를 확인할 수 없습니다."),
  SERVICE_UNAVAILABLE("SERVICE_UNAVAILABLE", 503, "서비스 이용 불가", "일시적으로 요청을 처리할 수 없습니다.");

  companion object {
    /** 상태 코드에 맞는 일반 코드. 목록에 없는 상태는 4xx면 BAD_REQUEST, 5xx면 INTERNAL_ERROR. */
    fun of(status: HttpStatusCode): ErrorCode =
      entries.firstOrNull {
        it.status == status.value() &&
          it !in
            setOf(
              VALIDATION_FAILED,
              INTERNAL_ACCESS_DENIED,
              GROUP_MEMBERSHIP_NOT_FOUND,
              GROUP_MEMBERSHIP_AMBIGUOUS,
            )
      } ?: if (status.is5xxServerError) INTERNAL_ERROR else BAD_REQUEST
  }
}
package task.group.presentation.error

import org.springframework.dao.DataAccessResourceFailureException
import org.springframework.http.*
import org.springframework.transaction.CannotCreateTransactionException
import org.springframework.web.bind.MethodArgumentNotValidException
import org.springframework.web.bind.annotation.ExceptionHandler
import org.springframework.web.bind.annotation.RestControllerAdvice
import org.springframework.web.context.request.WebRequest
import org.springframework.web.method.annotation.HandlerMethodValidationException
import org.springframework.web.servlet.mvc.method.annotation.ResponseEntityExceptionHandler
import task.group.application.exception.*

/** 의미 있는 예외를 고정 오류 계약으로 매핑한다(POL-API-002, POL-GROUP-001). */
@RestControllerAdvice
class ProblemDetailsExceptionHandler : ResponseEntityExceptionHandler() {
  @ExceptionHandler(InvalidGroupQueryException::class)
  fun invalid(ex: InvalidGroupQueryException) = problem(ErrorCode.VALIDATION_FAILED, ex)

  @ExceptionHandler(GroupMembershipNotFoundException::class)
  fun missing(ex: GroupMembershipNotFoundException) =
    problem(ErrorCode.GROUP_MEMBERSHIP_NOT_FOUND, ex)

  @ExceptionHandler(GroupMembershipAmbiguousException::class)
  fun ambiguous(ex: GroupMembershipAmbiguousException) =
    problem(ErrorCode.GROUP_MEMBERSHIP_AMBIGUOUS, ex)

  @ExceptionHandler(
    DataAccessResourceFailureException::class,
    CannotCreateTransactionException::class,
  )
  fun unavailable(ex: Exception) = problem(ErrorCode.SERVICE_UNAVAILABLE, ex)

  @ExceptionHandler(Exception::class)
  fun unexpected(ex: Exception) = problem(ErrorCode.INTERNAL_ERROR, ex)

  override fun handleExceptionInternal(
    ex: Exception,
    body: Any?,
    headers: HttpHeaders,
    statusCode: HttpStatusCode,
    request: WebRequest,
  ): ResponseEntity<Any>? {
    val code =
      when (ex) {
        is MethodArgumentNotValidException,
        is HandlerMethodValidationException -> ErrorCode.VALIDATION_FAILED
        else -> ErrorCode.of(statusCode)
      }
    return super.handleExceptionInternal(ex, problem(code, ex), headers, statusCode, request)
  }

  private fun problem(code: ErrorCode, ex: Exception): ProblemDetail {
    SafeErrorLog.record(code, ex)
    return GroupProblemDetail(
      ProblemDetail.forStatusAndDetail(HttpStatusCode.valueOf(code.status), code.description)
        .apply {
          title = code.codeName
          setProperty(CODE, code.code)
        }
    )
  }

  companion object {
    const val CODE = "code"
  }
}
package task.member.infrastructure.client.group

import java.io.IOException
import org.springframework.http.InvalidMediaTypeException
import org.springframework.http.MediaType
import org.springframework.web.client.ResourceAccessException
import org.springframework.web.client.RestClient
import org.springframework.web.client.RestClientException
import task.member.application.exception.GroupServiceConfigurationException
import task.member.application.exception.GroupServiceUnavailableException
import task.member.application.model.GroupMembership
import task.member.application.port.output.GroupMembershipReader

/** 목록과 상세를 의미별 경로로 전달한다. 페이지 크기로 API를 선택하지 않는다(POL-COMM-005). */
class HttpGroupMembershipReader(
  private val client: RestClient,
  private val decoder: GroupMembershipDecoder,
) : GroupMembershipReader {
  override fun findByMemberIds(memberIds: List<String>): Map<String, List<GroupMembership>> {
    GroupMembershipContract.validateRequest(memberIds)
    val response =
      read(
        client.get().uri { builder ->
          builder.path("/api/groups/summary")
          memberIds.forEach { builder.queryParam("memberIds", it) }
          builder.build()
        },
        allowMissing = false,
      )
    return decoder.decodeSummary(response.body, memberIds)
  }

  override fun findByMemberId(memberId: String): GroupMembership? {
    GroupMembershipContract.validateRequest(listOf(memberId))
    val response = read(client.get().uri("/api/group/{memberId}", memberId), allowMissing = true)
    if (response.status == 404) {
      if (decoder.isMembershipNotFound(response.body)) return null
      throw GroupServiceConfigurationException()
    }
    return decoder.decodeDetail(response.body, memberId)
  }

  private fun read(request: RestClient.RequestHeadersSpec<*>, allowMissing: Boolean): Payload =
    try {
      request.accept(MediaType.APPLICATION_JSON, MediaType.APPLICATION_PROBLEM_JSON).exchange {
        _,
        response ->
        val status = response.statusCode.value()
        if (response.statusCode.is5xxServerError) throw GroupServiceUnavailableException()
        if (status != 200 && !(allowMissing && status == 404))
          throw GroupServiceConfigurationException()
        val media =
          if (status == 404) MediaType.APPLICATION_PROBLEM_JSON else MediaType.APPLICATION_JSON
        val contentType = response.headers.contentType
        if (contentType == null || !media.isCompatibleWith(contentType))
          throw GroupServiceConfigurationException()
        val bytes = response.body.readNBytes(MAX_RESPONSE_BYTES + 1)
        if (bytes.size > MAX_RESPONSE_BYTES) throw GroupServiceConfigurationException()
        Payload(status, bytes)
      }
    } catch (_: ResourceAccessException) {
      throw GroupServiceUnavailableException()
    } catch (_: IOException) {
      throw GroupServiceUnavailableException()
    } catch (_: InvalidMediaTypeException) {
      throw GroupServiceConfigurationException()
    } catch (_: RestClientException) {
      throw GroupServiceConfigurationException()
    }

  private data class Payload(val status: Int, val body: ByteArray)

  private companion object {
    const val MAX_RESPONSE_BYTES = 1024 * 1024
  }
}

