import task.group.application.exception.InvalidGroupQueryException

/** 멤버 식별자 형식은 소비자 계약과 일치한다(POL-GROUP-001). */
data class MemberGroupDetailQuery(val memberId: String) {
  init {
    if (!memberId.matches(Regex("[a-z0-9]{10}"))) throw InvalidGroupQueryException()
  }
}
package task.group.application.exception

/** 원시 입력이나 데이터 내용을 예외 메시지에 담지 않는다(POL-API-002). */
class InvalidGroupQueryException : RuntimeException("그룹 조회 조건이 올바르지 않습니다.")

/** 미소속과 잘못된 HTTP 경로를 구분한다(POL-GROUP-001). */
class GroupMembershipNotFoundException : RuntimeException("그룹 소속을 찾을 수 없습니다.")

/** 복수 행을 대표 그룹으로 임의 선택하지 않는다(POL-GROUP-001). */
class GroupMembershipAmbiguousException : RuntimeException("단일 소속 조건에 맞지 않습니다.")
package task.group.application.query.summary

import org.slf4j.LoggerFactory
import org.springframework.stereotype.Service
import task.group.application.exception.GroupMembershipAmbiguousException
import task.group.application.model.GroupSummaryView
import task.group.application.port.input.GetGroupSummariesUseCase
import task.group.application.port.output.GroupSummaryReader

/** 트랜잭션 밖에서 그룹을 묶고 정렬한다(POL-GROUP-002, POL-CQRS-002). */
@Service
class GroupSummaryQueryHandler(private val reader: GroupSummaryReader) : GetGroupSummariesUseCase {
  private val log = LoggerFactory.getLogger(javaClass)

  override fun execute(query: GroupSummaryQuery): List<GroupSummaryView> {
    log.info("event=business.started operation=group.summary requested={}", query.memberIds.size)
    val snapshot = reader.findSummaries(query.memberIds)
    if (snapshot.memberships.map { it.memberId }.distinct().size != snapshot.memberships.size) {
      throw GroupMembershipAmbiguousException()
    }
    val result =
      snapshot.memberships
        .groupBy { it.groupId }
        .toSortedMap()
        .map { (id, members) ->
          GroupSummaryView(
            id,
            members.first().groupName,
            snapshot.counts.getValue(id),
            members.sortedBy { it.memberId },
          )
        }
    log.info(
      "event=business.completed operation=group.summary groups={} members={}",
      result.size,
      snapshot.memberships.size,
    )
    return result
  }
}
package task.group.presentation.error

import org.slf4j.LoggerFactory
import org.slf4j.MDC
import org.springframework.web.context.request.RequestContextHolder
import org.springframework.web.context.request.ServletRequestAttributes

/** 외부 메시지·SQL·본문을 포함할 수 있는 Throwable 원문을 기록하지 않는다(POL-CODE-004). */
internal object SafeErrorLog {
  private val log = LoggerFactory.getLogger(SafeErrorLog::class.java)

  fun record(code: ErrorCode, error: Exception? = null) {
    val request =
      (RequestContextHolder.getRequestAttributes() as? ServletRequestAttributes)?.request
    request?.setAttribute("errorCode", code.code)
    if (request?.getAttribute("exceptionLogged") == true) return
    request?.setAttribute("exceptionLogged", true)
    val frames =
      if (code.status >= 500) error?.stackTrace?.take(16)?.joinToString(" <- ") ?: "-" else "-"
    log.error(
      "event=exception.handled requestId={} stage=error.mapping code={} exception={} frames={}",
      MDC.get("requestId") ?: "-",
      code.code,
      error?.javaClass?.simpleName ?: code.code,
      frames,
    )
  }
}
package task.group.presentation.error

import com.fasterxml.jackson.annotation.JsonInclude
import java.net.URI
import org.springframework.http.ProblemDetail

/** about:blank type도 필수 필드로 직렬화한다(POL-API-002). */
class GroupProblemDetail(source: ProblemDetail) : ProblemDetail(source) {
  @JsonInclude(JsonInclude.Include.ALWAYS)
  override fun getType(): URI = super.getType() ?: URI.create("about:blank")
}

