        DelegatingOAuth2TokenValidator(
          JwtTimestampValidator(properties.clockSkew),
          JwtIssuerValidator(properties.issuer),
          JwtClaimValidator<Any?>(JwtClaimNames.AUD) { audience ->
            (audience as? Collection<*>)?.contains(properties.audience) == true
          },
          JwtClaimValidator<Any?>(JwtClaimNames.EXP) { it != null },
          JwtClaimValidator<Any?>(JwtClaimNames.SUB) { (it as? String)?.isNotBlank() == true },
