package task.group.application.query.summary

import task.group.application.exception.InvalidGroupQueryException
import task.group.application.exception.UnprocessableGroupQueryException

/**
 * 원시 ID 목록을 보정 없이 검증한 뒤 중복을 제외한다(POL-GROUP-002).
 *
 * 1. 누락(0개)·빈 값·형식 위반(소문자 영숫자 10자리 아님, 콤마 결합 포함)은 400이다. 중복 제거로 잘못된 값을 숨기지 않는다.
 * 2. 원래 입력 수가 100개를 넘으면 422다(중복 포함 개수).
 * 3. 중복은 거부하지 않는다. 처음 나온 순서로 한 번만 조회하고 중복된 ID는 [duplicateIds]로 남겨 처리기가 로그로 기록한다.
 */
data class GroupSummaryQuery(val requestedIds: List<String>) {
  init {
    if (requestedIds.isEmpty() || requestedIds.any { !ID.matches(it) }) {
      throw InvalidGroupQueryException()
    }
    if (requestedIds.size > MAX_IDS) throw UnprocessableGroupQueryException()
  }

  /** 중복을 제외한 조회 대상(입력 순서 유지). */
  val memberIds: List<String> = requestedIds.distinct()

  /** 두 번 이상 전달된 ID(처음 나온 순서). */
  val duplicateIds: List<String> =
    requestedIds.groupingBy { it }.eachCount().filterValues { it > 1 }.keys.toList()

  companion object {
    const val MAX_IDS = 100
    private val ID = Regex("[a-z0-9]{10}")
  }
}

package task.group.application.exception

/** 파라미터 형식 위반(400): 누락·빈 값·ID 형식·콤마 결합. 원시 입력을 예외 메시지에 담지 않는다(POL-API-002). */
class InvalidGroupQueryException : RuntimeException("그룹 조회 파라미터 형식이 올바르지 않습니다.")

/** 형식은 맞지만 처리할 수 없는 조건(422): memberIds 100개 초과(POL-GROUP-002). */
class UnprocessableGroupQueryException : RuntimeException("그룹 조회 조건을 처리할 수 없습니다.")

/** 미소속과 잘못된 HTTP 경로를 구분한다(POL-GROUP-001). */
class GroupMembershipNotFoundException : RuntimeException("그룹 소속을 찾을 수 없습니다.")

/** 복수 행을 대표 그룹으로 임의 선택하지 않는다(POL-GROUP-001). */
class GroupMembershipAmbiguousException : RuntimeException("단일 소속 조건에 맞지 않습니다.")

package task.group.presentation.error

import org.springframework.dao.DataAccessResourceFailureException
import org.springframework.http.HttpHeaders
import org.springframework.http.HttpStatusCode
import org.springframework.http.ProblemDetail
import org.springframework.http.ResponseEntity
import org.springframework.transaction.CannotCreateTransactionException
import org.springframework.web.bind.MethodArgumentNotValidException
import org.springframework.web.bind.annotation.ExceptionHandler
import org.springframework.web.bind.annotation.RestControllerAdvice
import org.springframework.web.context.request.WebRequest
import org.springframework.web.method.annotation.HandlerMethodValidationException
import org.springframework.web.servlet.mvc.method.annotation.ResponseEntityExceptionHandler
import task.group.application.exception.GroupMembershipAmbiguousException
import task.group.application.exception.GroupMembershipNotFoundException
import task.group.application.exception.InvalidGroupQueryException
import task.group.application.exception.UnprocessableGroupQueryException

/** 의미 있는 예외를 고정 오류 계약으로 매핑한다(POL-API-002, POL-GROUP-001). */
@RestControllerAdvice
class ProblemDetailsExceptionHandler : ResponseEntityExceptionHandler() {
  @ExceptionHandler(InvalidGroupQueryException::class)
  fun invalid(ex: InvalidGroupQueryException) = problem(ErrorCode.INVALID_PARAMETER, ex)

  @ExceptionHandler(UnprocessableGroupQueryException::class)
  fun unprocessable(ex: UnprocessableGroupQueryException) =
    problem(ErrorCode.VALIDATION_FAILED, ex)

  @ExceptionHandler(GroupMembershipNotFoundException::class)
  fun missing(ex: GroupMembershipNotFoundException) =
    problem(ProblemType.GROUP_MEMBERSHIP_NOT_FOUND, ex)

  @ExceptionHandler(GroupMembershipAmbiguousException::class)
  fun ambiguous(ex: GroupMembershipAmbiguousException) =
    problem(ProblemType.GROUP_MEMBERSHIP_AMBIGUOUS, ex)

  @ExceptionHandler(
    DataAccessResourceFailureException::class,
    CannotCreateTransactionException::class,
  )
  fun unavailable(ex: Exception) = problem(ErrorCode.SERVICE_UNAVAILABLE, ex)

  @ExceptionHandler(Exception::class)
  fun unexpected(ex: Exception) = problem(ErrorCode.INTERNAL_SERVER_ERROR, ex)

  override fun handleExceptionInternal(
    ex: Exception,
    body: Any?,
    headers: HttpHeaders,
    statusCode: HttpStatusCode,
    request: WebRequest,
  ): ResponseEntity<Any>? {
    // 본문 값 검증 실패는 형식이 아니라 의미 위반이므로 422로 응답한다.
    val code =
      when (ex) {
        is MethodArgumentNotValidException,
        is HandlerMethodValidationException -> ErrorCode.VALIDATION_FAILED
        else -> ErrorCode.of(statusCode)
      }
    return super.handleExceptionInternal(
      ex,
      problem(code, ex),
      headers,
      HttpStatusCode.valueOf(code.status),
      request,
    )
  }

  private fun problem(code: ErrorCode, ex: Exception): ProblemDetail {
    SafeErrorLog.record(code, ex)
    return Problems.of(code)
  }

  private fun problem(type: ProblemType, ex: Exception): ProblemDetail {
    SafeErrorLog.record(type.errorCode, ex, type = type)
    return Problems.of(type)
  }

  companion object {
    const val CODE = Problems.CODE
  }
}

package task.member.support

import jakarta.validation.Valid
