package task.member.infrastructure.web

import jakarta.servlet.FilterChain
import jakarta.servlet.http.HttpServletRequest
import jakarta.servlet.http.HttpServletResponse
import java.util.concurrent.ConcurrentHashMap
import kotlin.math.ceil
import kotlin.math.max
import kotlin.math.min
import org.springframework.boot.context.properties.ConfigurationProperties
import org.springframework.http.HttpHeaders
import org.springframework.security.core.context.SecurityContextHolder
import org.springframework.security.oauth2.server.resource.authentication.JwtAuthenticationToken
import org.springframework.web.filter.OncePerRequestFilter
import task.member.presentation.error.ErrorCode
import task.member.presentation.error.ProblemResponseWriter

/** 호출자별 요청 제한 조건(POL-SEC-007). 기본값은 정상 화면 사용을 막지 않는 수준이다. */
@ConfigurationProperties("task.rate-limit")
class RateLimitProperties(
  val enabled: Boolean = true,
  val capacity: Int = 100,
  val refillPerSecond: Int = 50,
  val maxClients: Int = 10_000,
) {
  init {
    require(capacity in 1..100_000) { "요청 제한 용량은 1~100000이어야 합니다." }
    require(refillPerSecond in 1..100_000) { "요청 제한 보충 속도는 1~100000이어야 합니다." }
    require(maxClients in 1..1_000_000) { "요청 제한 추적 호출자 수는 1~1000000이어야 합니다." }
  }
}

/**
 * 인증된 호출자(JWT sub)별 토큰 버킷. 서버 한 대의 메모리 안에서만 센다(분산 제한은 게이트웨이 책임).
 *
 * 추적 호출자가 상한을 넘으면 가득 찬(유휴) 버킷부터 지운다. 시간은 단조 시계(nanoTime)로 잰다.
 */
class TokenBucketRateLimiter(
  private val capacity: Int,
  private val refillPerSecond: Int,
  private val maxClients: Int,
  private val nanoTime: () -> Long = System::nanoTime,
) {
  private val buckets = ConcurrentHashMap<String, Bucket>()

  /** 허용하면 null, 거부하면 다시 시도할 수 있을 때까지의 초(1 이상)를 돌려준다. */
  fun tryAcquire(client: String): Long? {
    if (buckets.size >= maxClients && !buckets.containsKey(client)) evictIdle()
    return buckets.computeIfAbsent(client) { Bucket(capacity.toDouble(), nanoTime()) }.take()
  }

  private fun evictIdle() {
    val now = nanoTime()
    buckets.entries.removeIf { it.value.isFull(now) }
  }

  private inner class Bucket(private var tokens: Double, private var updatedAt: Long) {
    @Synchronized
    fun take(): Long? {
      refill(nanoTime())
      if (tokens >= 1.0) {
        tokens -= 1.0
        return null
      }
      return max(1L, ceil((1.0 - tokens) / refillPerSecond).toLong())
    }

    @Synchronized
    fun isFull(now: Long): Boolean {
      refill(now)
      return tokens >= capacity
    }

    private fun refill(now: Long) {
      val elapsed = max(0L, now - updatedAt)
      tokens = min(capacity.toDouble(), tokens + elapsed / 1_000_000_000.0 * refillPerSecond)
      updatedAt = now
    }
  }
}

/** 보안 필터가 인증한 뒤 업무·중계 경로에만 적용한다. 초과하면 429와 Retry-After를 돌려준다(POL-SEC-007). */
class RateLimitFilter(
  private val limiter: TokenBucketRateLimiter,
  private val writer: ProblemResponseWriter,
) : OncePerRequestFilter() {
  override fun shouldNotFilter(request: HttpServletRequest): Boolean {
    val path = request.requestURI.removePrefix(request.contextPath)
    return LIMITED_PREFIXES.none { path.startsWith(it) }
  }

  override fun doFilterInternal(
    request: HttpServletRequest,
    response: HttpServletResponse,
    chain: FilterChain,
  ) {
    val authentication = SecurityContextHolder.getContext().authentication as? JwtAuthenticationToken
    if (authentication == null) {
      chain.doFilter(request, response)
      return
    }
    val retryAfter = limiter.tryAcquire(authentication.name)
    if (retryAfter == null) {
      chain.doFilter(request, response)
      return
    }
    response.setHeader(HttpHeaders.RETRY_AFTER, retryAfter.toString())
    writer.write(request, response, ErrorCode.TOO_MANY_REQUESTS)
  }

  companion object {
    val LIMITED_PREFIXES = listOf("/api/", "/internal-api/")
  }
}
package task.member.infrastructure.web

import jakarta.servlet.FilterChain
import jakarta.servlet.http.HttpServletRequest
import jakarta.servlet.http.HttpServletResponse
import org.springframework.http.HttpHeaders
import org.springframework.web.filter.OncePerRequestFilter
import task.member.presentation.error.ErrorCode
import task.member.presentation.error.ProblemResponseWriter

/**
 * 제공하는 API는 모두 GET이다. HEAD·OPTIONS·POST·PUT·PATCH·DELETE·TRACE 등은 인증·핸들러 실행 전에 405로 막는다(POL-API-008).
 *
 * Spring MVC의 암묵 HEAD·OPTIONS 처리가 핸들러와 원격 호출을 실행하지 않도록 가장 앞쪽(요청 추적 다음)에서 판단한다.
 */
class GetOnlyMethodFilter(private val writer: ProblemResponseWriter) : OncePerRequestFilter() {
  override fun doFilterInternal(
    request: HttpServletRequest,
    response: HttpServletResponse,
    chain: FilterChain,
  ) {
    if (request.method == ALLOWED) {
      chain.doFilter(request, response)
      return
    }
    response.setHeader(HttpHeaders.ALLOW, ALLOWED)
    writer.write(request, response, ErrorCode.METHOD_NOT_ALLOWED)
  }

  /** 오류 디스패치도 같은 규칙을 적용한다. */
  override fun shouldNotFilterErrorDispatch() = false

  companion object {
    const val ALLOWED = "GET"
  }
}
package task.member.infrastructure.web

import org.springframework.boot.context.properties.EnableConfigurationProperties
import org.springframework.boot.web.servlet.FilterRegistrationBean
import org.springframework.context.annotation.Bean
import org.springframework.context.annotation.Configuration
import org.springframework.core.Ordered
import task.member.presentation.error.ProblemResponseWriter
import tools.jackson.databind.json.JsonMapper

/**
 * 요청 추적(HIGHEST_PRECEDENCE) → GET 전용 검사 → Spring Security(-100) → 요청 제한 → MVC 순서로 실행한다.
 *
 * 메서드 거부는 인증보다 먼저, 요청 제한은 인증된 호출자를 안 뒤에 판단한다.
 */
@Configuration(proxyBeanMethods = false)
@EnableConfigurationProperties(RateLimitProperties::class)
class WebFilterConfiguration {
  @Bean
  fun getOnlyMethodFilter(mapper: JsonMapper) =
    FilterRegistrationBean(GetOnlyMethodFilter(ProblemResponseWriter(mapper))).apply {
      order = Ordered.HIGHEST_PRECEDENCE + 1
      addUrlPatterns("/*")
    }

  @Bean
  fun rateLimitFilter(properties: RateLimitProperties, mapper: JsonMapper) =
    FilterRegistrationBean(
        RateLimitFilter(
          TokenBucketRateLimiter(
            properties.capacity,
            properties.refillPerSecond,
            properties.maxClients,
          ),
          ProblemResponseWriter(mapper),
        )
      )
      .apply {
        order = SECURITY_FILTER_ORDER + 1
        isEnabled = properties.enabled
        addUrlPatterns("/*")
      }

  companion object {
    /** Spring Boot의 Spring Security 필터 체인 기본 순서(SecurityProperties.DEFAULT_FILTER_ORDER). */
    const val SECURITY_FILTER_ORDER = -100
  }
}
package task.member.infrastructure.configuration

import jakarta.servlet.FilterChain
import jakarta.servlet.http.HttpServletRequest
import jakarta.servlet.http.HttpServletResponse
import org.springframework.beans.factory.ObjectProvider
import org.springframework.beans.factory.annotation.Value
import org.springframework.boot.web.servlet.FilterRegistrationBean
import org.springframework.context.annotation.Bean
import org.springframework.context.annotation.Configuration
import org.springframework.core.io.ClassPathResource
import org.springframework.web.filter.OncePerRequestFilter
import task.member.infrastructure.security.LocalAccessTokenIssuer
import tools.jackson.databind.json.JsonMapper

/**
 * 같은 화면에서 멤버 API와 (local 중계가 켜졌을 때) 멤버 경유 그룹 API를 실행한다(POL-API-004).
 *
 * local 프로필에서는 요청마다 짧은 만료의 접근 토큰을 서명해 초기화 스크립트에 넣는다(POL-SEC-005). 내부 호출 키는 넣지 않는다.
 */
@Configuration(proxyBeanMethods = false)
class SwaggerUiConfiguration {
  @Bean
  fun swaggerInitializerFilter(
    issuer: ObjectProvider<LocalAccessTokenIssuer>,
    mapper: JsonMapper,
    @Value("\${task.group-proxy.enabled:false}") groupProxyEnabled: Boolean,
  ): FilterRegistrationBean<SwaggerInitializerFilter> =
    FilterRegistrationBean(
        SwaggerInitializerFilter(issuer.ifAvailable, mapper, groupProxyEnabled)
      )
      .apply { addUrlPatterns(INITIALIZER_PATH) }

  companion object {
    const val INITIALIZER_PATH = "/swagger-ui/swagger-initializer.js"
  }
}

/** 정적 초기화 스크립트 앞에 실행 설정(local 토큰, 그룹 중계 사용 여부)만 덧붙인다. 응답은 캐시하지 않는다. */
class SwaggerInitializerFilter(
  private val issuer: LocalAccessTokenIssuer?,
  private val mapper: JsonMapper,
  private val groupProxyEnabled: Boolean,
) : OncePerRequestFilter() {
  private val script =
    ClassPathResource("swagger/initializer.js").inputStream.use { it.readBytes() }

  override fun doFilterInternal(
    request: HttpServletRequest,
    response: HttpServletResponse,
    chain: FilterChain,
  ) {
    val token = issuer?.issue()
    val settings =
      linkedMapOf<String, Any?>(
        "accessToken" to token?.value,
        "accessTokenExpiresAt" to token?.expiresAtEpochSecond,
        "groupProxyEnabled" to groupProxyEnabled,
      )
    response.contentType = "application/javascript"
    response.characterEncoding = "UTF-8"
    response.setHeader("Cache-Control", "no-store")
    response.outputStream.write(
      "window.taskSwaggerSettings = ${mapper.writeValueAsString(settings)};\n"
        .toByteArray(Charsets.UTF_8)
    )
    response.outputStream.write(script)
  }
}

