import sys

root = sys.argv[1]


def edit(path, pairs):
    p = root + "/" + path
    s = open(p, encoding="utf-8").read()
    for old, new in pairs:
        if old not in s:
            raise SystemExit("not found in " + path + ": " + old[:80])
        s = s.replace(old, new)
    open(p, "w", encoding="utf-8").write(s)


