  @PostMapping("/validated") fun validated(@Valid @RequestBody body: ProbeBody) = body

  @GetMapping("/boom") fun boom(): Map<String, Any> = error("내부 상세 정보")

  data class ProbeBody(@field:NotBlank val name: String?)
}

